package editspec

import (
	"encoding/json"
	"os"
	"reflect"
	"strings"
	"testing"
)

// schema/templates.json is the one template catalog shared by Go and the Remotion
// package. It is generated by `metarush schema export`; this test fails when it
// is stale (drift = renders recording the wrong versions or regions).
func TestTemplateCatalogIsCurrent(t *testing.T) {
	b, err := os.ReadFile("../../schema/templates.json")
	if err != nil {
		t.Fatalf("schema/templates.json missing (run `metarush schema export --dir schema`): %v", err)
	}
	var got TemplateCatalog
	if err := json.Unmarshal(b, &got); err != nil {
		t.Fatal(err)
	}
	want := Catalog()
	if !reflect.DeepEqual(stripped(got.Templates), stripped(want.Templates)) {
		t.Fatalf("schema/templates.json is stale; run `metarush schema export --dir schema`\n got: %+v\nwant: %+v", got.Templates, want.Templates)
	}
}

// The Remotion package must read the catalog (no second copy) and register a
// component for every template in it.
func TestRemotionUsesTheCatalog(t *testing.T) {
	reg, err := os.ReadFile("../../video/src/templates/registry.tsx")
	if err != nil {
		t.Skip("video package not present")
	}
	src := string(reg)
	if !strings.Contains(src, "@metarush/schema/schemas/templates.json") {
		t.Error("video/src/templates/registry.tsx must import the generated catalog (@metarush/schema/schemas/templates.json)")
	}
	if _, err := os.Stat("../../video/src/templates/manifest.json"); err == nil {
		t.Error("video/src/templates/manifest.json is a hand-kept copy of the catalog; delete it")
	}
	for _, tpl := range Templates {
		if !strings.Contains(src, "'"+tpl.ID+"':") {
			t.Errorf("template %s has no component registered in registry.tsx", tpl.ID)
		}
	}
	shared, err := os.ReadFile("../../video/render/shared.mjs")
	if err == nil && !strings.Contains(string(shared), "@metarush/schema/schemas/templates.json") {
		t.Error("video/render/shared.mjs must read the generated catalog for its versions line")
	}
}

// stripped drops unexported fields (params) so the comparison is the JSON shape.
func stripped(ts []TemplateInfo) []TemplateInfo {
	out := make([]TemplateInfo, len(ts))
	for i, t := range ts {
		out[i] = TemplateInfo{ID: t.ID, Version: t.Version, Summary: t.Summary, MinDuration: t.MinDuration, MaxDuration: t.MaxDuration, Region: t.Region}
	}
	return out
}
